import os
from google.cloud import kms_v1

def sign_message(key_id: str, message: bytes) -> bytes:
    client = kms_v1.KeyManagementServiceClient()
    response = client.asymmetric_sign(
        name=key_id,
        digest={
            'sha256': kms_v1.Digest(sha256=kms_v1.HashOperation(data=message))
        }
    )
    return response.signature

def verify_signature(key_id: str, message: bytes, signature: bytes) -> bool:
    client = kms_v1.KeyManagementServiceClient()
    try:
        client.asymmetric_verify(
            name=key_id,
            digest={
                'sha256': kms_v1.Digest(sha256=kms_v1.HashOperation(data=message))
            },
            signature=signature
        )
        return True
    except Exception:
        return False
